<tr><th scope="row">Entry annual price</th><td>Growth: US$19 per agent/month</td><td>Support Team: US$19 per agent/month</td></tr>
<tr><th scope="row">Next listed tier</th><td>Pro: US$55 per agent/month</td><td>Suite Team: US$55 per agent/month</td></tr>
